/* ==========================================================================
 *  NORMALIZACJA I WALIDACJA ZGŁOSZENIA
 * --------------------------------------------------------------------------
 *  Wejście: surowe ciało żądania z węzła Webhook.
 *    • form-urlencoded  → pola lądują w $json.body
 *    • JSON             → też w $json.body (n8n parsuje sam)
 *
 *  Wyjście: JEDEN obiekt o kluczach dokładnie takich, jak nagłówki kolumn
 *  w zakładce „Rezerwacje". Dzięki temu węzeł Google Sheets mapuje je 1:1
 *  i dodanie kolumny w arkuszu nie wymaga zmiany mapowania.
 * ========================================================================== */

const body = $input.first().json.body ?? $input.first().json;

/** Pierwsza niepusta wartość z listy aliasów (front używa innych nazw niż arkusz). */
const pierwszy = (...klucze) => {
  for (const k of klucze) {
    const v = body[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

const naDate = (v) => (String(v).match(/^\d{4}-\d{2}-\d{2}/) || [''])[0];

const naGodzine = (v) => {
  const m = String(v).match(/^(\d{1,2}):(\d{2})/);
  return m ? String(m[1]).padStart(2, '0') + ':' + m[2] : '';
};

/** Same cyfry, bez prefiksu kierunkowego — arkusz ma mieć jeden format numeru. */
const naTelefon = (v) => {
  let c = String(v).replace(/\D/g, '');
  if (c.length === 11 && c.startsWith('48')) c = c.slice(2);
  if (c.length === 13 && c.startsWith('0048')) c = c.slice(4);
  return c;
};

const d = {
  jednostka: pierwszy('jednostka', 'unitType', 'unitName', 'Jednostka'),
  dataRejsu: naDate(pierwszy('dataRejsu', 'date', 'DataRejsu')),
  godzina: naGodzine(pierwszy('godzina', 'timeSlot', 'Godzina')),
  imie: pierwszy('imie', 'clientName', 'Imie'),
  telefon: naTelefon(pierwszy('telefon', 'clientPhone', 'Telefon')),
  miejsca: parseInt(pierwszy('miejsca', 'seatsCount', 'Miejsca') || '0', 10),
  zrodlo: pierwszy('zrodlo', 'source', 'Zrodlo') || 'WWW-n8n',
};

/* Walidacja serwerowa. Przeglądarka sprawdza to samo, ale walidacja po stronie
 * klienta jest wygodą użytkownika, nie zabezpieczeniem — webhook jest publiczny
 * i każdy może w niego strzelić curl-em. */
const bledy = [];
if (!d.jednostka) bledy.push('Brak nazwy jednostki.');
if (!/^\d{4}-\d{2}-\d{2}$/.test(d.dataRejsu)) bledy.push('Data rejsu musi miec format RRRR-MM-DD.');
if (!/^\d{2}:\d{2}$/.test(d.godzina)) bledy.push('Godzina musi miec format GG:MM.');
if (d.imie.length < 3) bledy.push('Imie i nazwisko: minimum 3 znaki.');
if (!/^\d{9,12}$/.test(d.telefon)) bledy.push('Numer telefonu: 9-12 cyfr.');
if (!(d.miejsca >= 1 && d.miejsca <= 60)) bledy.push('Liczba miejsc poza zakresem 1-60.');

if (bledy.length === 0) {
  const dzis = new Date();
  dzis.setHours(0, 0, 0, 0);
  if (new Date(d.dataRejsu + 'T00:00:00') < dzis) bledy.push('Data rejsu jest z przeszlosci.');
}

/* Znacznik czasu w strefie Europe/Warsaw. Locale 'sv-SE' to najkrótsza droga
 * do formatu „RRRR-MM-DD GG:MM" — szwedzki zapis daty jest zgodny z ISO 8601. */
const stempel = new Date()
  .toLocaleString('sv-SE', { timeZone: 'Europe/Warsaw' })
  .slice(0, 16);

/* ⚠️ RÓŻNICA WZGLĘDEM APPS SCRIPT: ten przepływ nie czyta arkusza przed
 * zapisem, więc nie zna numeru porządkowego w slocie. Zamiast licznika
 * doklejamy 4-znakowy losowy sufiks — kolizja jest praktycznie niemożliwa,
 * a ID dalej da się podyktować przez telefon. */
const skrot = d.jednostka.toUpperCase().includes('RIB') ? 'RIB' : 'STA';
const id = bledy.length
  ? ''
  : 'MS-' + d.dataRejsu.slice(2).replace(/-/g, '') +
    '-' + d.godzina.replace(':', '') +
    '-' + skrot +
    '-' + Math.random().toString(36).slice(2, 6).toUpperCase();

return [{
  json: {
    ok: bledy.length === 0,
    bledy,
    ID: id,
    DataWpisu: stempel,
    DataRejsu: d.dataRejsu,
    Godzina: d.godzina,
    Jednostka: d.jednostka,
    Imie: d.imie,
    Telefon: d.telefon,
    Miejsca: d.miejsca,
    Status: 'NOWA',
    Zrodlo: d.zrodlo,
  },
}];

